script:
today = frappe.utils.today()
active_status = "Vertretung ist aktiv"
inactive_status = "Vertretung nicht aktiv"

active_assignments = frappe.get_all(
    "Vertretung Freigabe",
    filters={"von": ["<=", today], "bis": [">=", today], "vertretung_aktiv": 1},
    fields=["name", "vertreter"],
)

for assignment in active_assignments:
    if not assignment["vertreter"]:
        continue

    frappe.call(
        "vepro_app.api.set_vertretung_freigabe_role",
        user=assignment["vertreter"],
        enabled=True,
    )

    if frappe.db.get_value("Vertretung Freigabe", assignment["name"], "status") != active_status:
        frappe.db.set_value("Vertretung Freigabe", assignment["name"], "status", active_status)

expired = frappe.get_all(
    "Vertretung Freigabe",
    filters={"bis": ["<", today]},
    fields=["name", "vertreter", "status"],
)

for assignment in expired:
    if assignment["status"] != inactive_status:
        frappe.db.set_value("Vertretung Freigabe", assignment["name"], "status", inactive_status)

    if not assignment["vertreter"]:
        continue

    current_assignments = frappe.get_all(
        "Vertretung Freigabe",
        filters={
            "vertreter": assignment["vertreter"],
            "vertretung_aktiv": 1,
            "von": ["<=", today],
        },
        fields=["bis"],
    )
    has_current_assignment = False
    for current_assignment in current_assignments:
        if not current_assignment["bis"] or frappe.utils.getdate(current_assignment["bis"]) >= frappe.utils.getdate(today):
            has_current_assignment = True
            break

    if has_current_assignment:
        continue

    frappe.call(
        "vepro_app.api.set_vertretung_freigabe_role",
        user=assignment["vertreter"],
        enabled=False,
    )
